mapper.select:
SELECT a.bim_tree_id,a.project_id,b.p_name as project_name FROM PROJECT_BIM_TREE_MAP a LEFT JOIN Pre_Project b ON a.project_id = b.p_id
a.bim_tree_id in
#{item}

select a.p_id as project_id, a.p_name as project_name, a.p_type as projectType from PRE_PROJECT a
a.p_id in
#{item}

select a.con_id as contract_id, a.con_name as contract_name, a.Con_Code as contract_code from CON_CONTRACT a
a.con_id in
#{item}

select mn.qsr_id, con.Con_Name as con_name, mn.P_Id as project_id, mn.qsr_category as qsr_type, mn.qsr_type as check_type, qt.Qst_Name as problem_category, mn.qsr_problem_nature as problemNature, mn.qsr_time as check_time, mn.qsr_rectify_require_time as rectify_require_time, mn.qsr_rectify_uame as rectify_user_name from Qs_Record mn left join Qs_Type qt on qt.Qst_Id=mn.Qst_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
mn.qsr_id in
#{item}

SELECT count(*) FROM Qs_Record a
WHERE a.biz_id IN
    
        #{item}
    
    
        and a.Qsr_Rectify_Status = #{rectifyStatus}
    
 and a.Pt_Id IN (
    SELECT mn.id FROM Qs_Plan_Task mn WHERE mn.Pt_Type = '03' and mn.Pt_Category = '02'
        
            and to_char(mn.Pt_Evaluation_Time,'yyyy/MM/dd') >= #{startTime}
        
        
            and to_char(mn.Pt_Evaluation_Time,'yyyy/MM/dd') <= #{endTime}
        
)

SELECT count(*) FROM Qs_Record a
WHERE a.biz_id IN
    
        #{item}
    
    
        and a.Qsr_Rectify_Status = #{rectifyStatus}
    
and a.Pt_Id IN (
SELECT mn.id FROM Qs_Plan_Task mn WHERE mn.Pt_Type = '03' and mn.Pt_Category = '02'
    
        and DATE_FORMAT(mn.Pt_Evaluation_Time,'%Y/%m/%d') >= #{startTime}
    
    
        and DATE_FORMAT(mn.Pt_Evaluation_Time,'%Y/%m/%d') <= #{endTime}
    
)

select a.qsr_des as problemDesc
from qs_record a
where a.qsr_des is not null
and a.Pt_Id IN (
SELECT mn.id FROM Qs_Plan_Task mn WHERE mn.Pt_Category = '02' and mn.P_ID = #{projectId}

    and DATE_FORMAT(mn.Pt_Evaluation_Time,'%Y/%m/%d') >= #{startTime}


    and DATE_FORMAT(mn.Pt_Evaluation_Time,'%Y/%m/%d') <= #{endTime}

)

select a.qsr_des as problemDesc
from qs_record a
where a.qsr_des is not null
and a.Pt_Id IN (
SELECT mn.id FROM Qs_Plan_Task mn WHERE mn.Pt_Category = '02' and mn.P_ID = #{projectId}

    and to_char(mn.Pt_Evaluation_Time,'yyyy/MM/dd') >= #{startTime}


    and to_char(mn.Pt_Evaluation_Time,'yyyy/MM/dd') <= #{endTime}

)
